import "./StatusMessage.css";

export interface StatusMessageProps {
  text: string;
  onDismiss: () => void;
}

export function StatusMessage({ text, onDismiss }: StatusMessageProps) {
  return (
    // The live region is always in the DOM. Screen readers announce text
    // that is inserted into an existing status region, but often skip a
    // region that is mounted together with its content.
    <div role="status" className="status-message">
      {text.length > 0 && (
        <div className="status-message__body">
          <p className="status-message__text">{text}</p>
          <button
            type="button"
            className="status-message__dismiss"
            onClick={onDismiss}
          >
            Dismiss
          </button>
        </div>
      )}
    </div>
  );
}
