.status-message {
  font: inherit;
}

.status-message__body {
  display: flex;
  align-items: center;
  gap: clamp(0.5rem, 1.5vw, 1rem);
  padding: clamp(0.5rem, 1.2vw, 0.75rem) clamp(0.75rem, 2vw, 1.25rem);
  border-left: 3px solid var(--myelin);
  border-radius: 0.5rem;
  background: var(--myelin-wash);
  color: var(--ink);
  font: inherit;
  animation: status-message-in 200ms ease-out both;
}

.status-message__text {
  flex: 1 1 auto;
  margin: 0;
  font-size: clamp(0.875rem, 0.8rem + 0.4vw, 1.0625rem);
  line-height: 1.4;
  color: var(--ink);
}

.status-message__dismiss {
  flex: 0 0 auto;
  font: inherit;
  font-size: clamp(0.8125rem, 0.75rem + 0.3vw, 0.9375rem);
  color: var(--ink);
  background: transparent;
  border: 1px solid var(--ink);
  border-radius: 999px;
  padding: 0.25em 0.9em;
  cursor: pointer;
  transition: border-color 150ms ease, color 150ms ease;
}

.status-message__dismiss:hover {
  border-color: var(--myelin);
  color: var(--myelin);
}

/* Focus outline comes from the global :focus-visible rule. Do not remove it here. */

@keyframes status-message-in {
  from {
    opacity: 0;
    transform: translateY(-0.25rem);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

:root[data-motion="reduce"] .status-message__body,
:root[data-motion="reduce"] .status-message__dismiss {
  animation: none;
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .status-message__body,
  .status-message__dismiss {
    animation: none;
    transition: none;
  }
}
